#include <iostream>

// Function prototype
int maximum(int x, int y, int z);

int main() {
    int grade1 = 0;
    int grade2 = 0;
    int grade3 = 0;

    if (std::cin >> grade1 >> grade2 >> grade3) {
        // Arguments evaluated cleanly
        int maxGrade = maximum(grade1, grade2, grade3);
        std::cout << "Maximum grade: " << maxGrade << "\n";
    }

    return 0;
}

// Function definition with 3 distinct typed parameters
int maximum(int x, int y, int z) {
    int maximumValue = x; // Assume x is largest initially

    if (y > maximumValue) {
        maximumValue = y;
    }
    if (z > maximumValue) {
        maximumValue = z;
    }

    return maximumValue;
}

#include <iostream>

// Prototype expecting double: int arguments will be promoted seamlessly
double computeArea(double side);

// Prototype expecting int: floating-point arguments will be truncated
int square(int value);

int main() {
    int length = 5;
    // Argument coercion: int promoted to double
    double area = computeArea(length);
    std::cout << "Area with int arg: " << area << "\n";

    // Narrowing conversion: 4.5 truncated to int 4
    int sq = square(4.5);
    std::cout << "Square of 4.5 truncated: " << sq << "\n";

    return 0;
}

double computeArea(double side) {
    return side * side;
}

int square(int value) {
    return value * value;
}
